#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_all_non_zero(void) {
    // Setup: Build a linked list with at least two nodes.
    // The target node is NOT the head.
    // All update parameters (ct, wt, tat) are non-zero.
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;
    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial CT, WT, TAT are zero (as set by insert)
    node *ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Test: Update node with ID=2 (non-head) with all non-zero values.
    // Path conditions:
    // 1. ptr != NULL && ptr->ID == id? -> false (head ID is 1, target is 2)
    // 2. Traverse loop: (ptr != NULL && ptr->ID != id) -> true until found
    // 3. ct != 0 -> true -> assign
    // 4. wt != 0 -> true -> assign
    // 5. tat != 0 -> true -> assign
    int new_ct = 10;
    int new_wt = 4;
    int new_tat = 9;
    update((node**)&root, 2, new_ct, new_wt, new_tat);

    // Assertions: Verify the target node fields are updated.
    ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(new_ct, ptr->CT);
    TEST_ASSERT_EQUAL_INT(new_wt, ptr->WT);
    TEST_ASSERT_EQUAL_INT(new_tat, ptr->TAT);

    // Verify other nodes are unchanged (head node ID=1 should still have zeros).
    ptr = root; // head
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}


